import raw from '../atlas-review/public/models/bodyparts3d/full-body/catalog.json';
import review from '../atlas-review/manifest.json';
import learner from '../public/atlas-runtime/head-neck/manifest.json';
import limb from '../public/atlas-runtime/lower-limb/manifest.json';
import viewer from '../public/atlas-review-viewer/manifest.json';
import {bodyDisplayCatalog} from '../atlas-review/lib/body-display-catalog';
import type {BodyCatalog} from '../atlas-review/app/body-types';
import {parseStudyLink,resolveStudyLink} from '../atlas-review/lib/study-links';
import {makeSpecimenLink,resolveSpecimenLink} from '../atlas-review/lib/um-limb-navigation';
import {parseSpecimenLink} from '../atlas-review/lib/specimen-links';
import {kneeDefinition} from '../atlas-review/lib/um-limb-studies';
import {kneeReferenceSpecs,kneeBodyReferenceId,kneeReferencePin} from './regional-knee-3d-mappings';
import {buildRegionalLearningCatalogue} from './regional-mri-learning-catalogue';
import type {Regional3dCatalogue,Regional3dTarget} from './regional-mri-3d-comparison';
const canonical=bodyDisplayCatalog(raw as unknown as BodyCatalog);
const identities=new Map(canonical.structures.map(s=>[s.id,JSON.stringify(s)]));
const bundles=new Map(canonical.bundles.map(b=>[b.id,JSON.stringify(b)]));
type Binding={reviewRevision:unknown;learnerRevision:unknown;limbRevision:unknown;viewerRevision:unknown;reviewIntegration:unknown;viewerIntegration:unknown};
const current:Binding={reviewRevision:review.revision,learnerRevision:learner.sourceCommit,limbRevision:limb.sourceCommit,viewerRevision:viewer.sourceCommit,
 reviewIntegration:review.websiteIntegrationSha256,viewerIntegration:viewer.websiteIntegrationSha256};
/** Server projection only: original catalogue coordinates and source scans never reach the client. */
export async function buildRegionalMri3dCatalogue(source:{revision:string;region:string},catalog:BodyCatalog=canonical,binding:Binding=current):Promise<Regional3dCatalogue|null>{
 if(source.region!=='knee'||!/^[a-f0-9]{64}$/.test(source.revision)||typeof binding.reviewRevision!=='string'||! /^[a-f0-9]{40}$/.test(binding.reviewRevision)||
  [binding.learnerRevision,binding.limbRevision,binding.viewerRevision].some(r=>r!==binding.reviewRevision)||typeof binding.reviewIntegration!=='string'||
  !/^[a-f0-9]{64}$/.test(binding.reviewIntegration)||binding.reviewIntegration!==binding.viewerIntegration)return null;
 const revision=binding.reviewRevision,entries:Regional3dCatalogue['entries']=[];
 for(const side of ['left','right'] as const)for(const anatomyId of [...new Set(kneeReferenceSpecs.map(s=>s.anatomyId))]){
  const targets:Regional3dTarget[]=[];
  for(const spec of kneeReferenceSpecs.filter(s=>s.anatomyId===anatomyId)){
   const pin=kneeReferencePin(spec,side);
   if(spec.kind==='body'){
    const id=kneeBodyReferenceId(spec,side)!,matches=catalog.structures.filter(s=>s.id===id);if(matches.length!==1)continue;
    const s=matches[0],matchesBundle=catalog.bundles.filter(b=>b.id===s.bundle);if(matchesBundle.length!==1)continue;
    const bundle=matchesBundle[0];if(identities.get(id)!==JSON.stringify(s)||bundles.get(bundle.id)!==JSON.stringify(bundle)||s.laterality!==side||bundle.sha256!==pin.sourceHash||s.name!==pin.label)continue;
    const params={study:'1',structure:id,side,source:bundle.sha256};
    if(resolveStudyLink(catalog,spec.region,parseStudyLink(params)).status!=='ready')continue;
    targets.push({kind:'body',id,label:s.name,side,region:spec.region as 'leg'|'thigh',sourceHash:bundle.sha256,specimenRevision:null,relation:spec.relation,
     href:'/atlas/3d?'+new URLSearchParams({region:spec.region,...params,atlasRevision:revision})});
   }else{
    const s=kneeDefinition.surfaces.find(s=>s.slug===spec.slug);if(!s||s.laterality!=='right-source-report')continue;
    const href=makeSpecimenLink(kneeDefinition,{selectedId:s.id,view:'anterior'});if(!href)continue;
    const url=new URL(href,'https://visible-medicine.invalid'),parsed=parseSpecimenLink(Object.fromEntries(url.searchParams));
    if(resolveSpecimenLink(parsed).status!=='ready'||parsed.status!=='requested'||parsed.request.sourceHash!==pin.sourceHash||parsed.request.revision!==pin.specimenRevision||s.name!==pin.label)continue;
    targets.push({kind:'specimen',id:s.id,label:s.name,side:'right',region:'knee',sourceHash:parsed.request.sourceHash,specimenRevision:parsed.request.revision,
     relation:spec.relation,href:'/atlas/lower-limb-3d?'+url.searchParams+'&atlasRevision='+revision});
   }
  }
  if(targets.length)entries.push({anatomyId,sourceSide:side,targets});
 }
 const bytes=new TextEncoder().encode(JSON.stringify({version:1,atlasRevision:revision,entries}));
 const digest=await crypto.subtle.digest('SHA-256',bytes),mappingRevision=Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');
 const result:Regional3dCatalogue={schema:'visible-medicine.regional-mri-3d/1',mriRevision:source.revision,atlasRevision:revision,mappingRevision,entries};
 const learning=await buildRegionalLearningCatalogue(result,catalog);
 if(learning)result.learning=learning;
 return result;
}
export const regionalMri3dCatalogue=buildRegionalMri3dCatalogue;

import review from '../atlas-review/manifest.json';
import type {Regional3dCatalogue,Regional3dTarget} from './regional-mri-3d-comparison.ts';
import {regionalLearningEntryValid,regionalLearningRevision,type RegionalLearningEntry} from './regional-mri-learning.ts';
import {parseRegionalLearningReviewRequest,type RegionalLearningReviewRequest} from './regional-mri-learning-review-link.ts';

export type RegionalLearningReviewSnapshot=Readonly<{
 atlasRevision:string;mappingRevision:string;entry:Readonly<RegionalLearningEntry>;
}>;
const hash=/^[a-f0-9]{64}$/,commit=/^[a-f0-9]{40}$/;
const exact=(value:unknown,keys:string[]):value is Record<string,unknown>=>!!value&&typeof value==='object'&&!Array.isArray(value)&&
 Object.keys(value).sort().join('|')===[...keys].sort().join('|');
const digest=async(value:unknown)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(value)))),
 n=>n.toString(16).padStart(2,'0')).join('');
function freeze<T>(value:T):T{if(value&&typeof value==='object'){for(const child of Object.values(value))freeze(child);Object.freeze(value);}return value;}
function identity(target:Regional3dTarget){return {id:target.id,kind:target.kind,label:target.label,side:target.side,
 sourceHash:target.sourceHash,specimenRevision:target.specimenRevision,relation:target.relation};}
function sameIdentity(a:object,b:object){
 const left=a as Record<string,unknown>,right=b as Record<string,unknown>;
 return Object.keys(left).length===Object.keys(right).length&&Object.keys(left).every(key=>left[key]===right[key]);
}

/** A revision-bound public teaching snapshot. Authorization belongs to the route. */
export async function resolveRegionalLearningReview(request:RegionalLearningReviewRequest,catalogue:Regional3dCatalogue|null):Promise<RegionalLearningReviewSnapshot|null>{
 try{
  // Own all inputs before the first digest await, including the public mapping.
  const r=parseRegionalLearningReviewRequest(structuredClone(request)),c=structuredClone(catalogue);
  if(!r||!c||
   !exact(c,['schema','mriRevision','atlasRevision','mappingRevision','entries','learning'])||
   c.schema!=='visible-medicine.regional-mri-3d/1'||!hash.test(c.mriRevision)||
   !commit.test(r.atlasRevision)||r.atlasRevision!==review.revision||c.atlasRevision!==r.atlasRevision||
   !hash.test(r.mappingRevision)||c.mappingRevision!==r.mappingRevision||!hash.test(r.teachingRevision)||
   typeof r.target!=='string'||!r.target||r.target.length>240||
   !['same-structure','parent-reference','group-reference'].includes(r.relation)||
   !Array.isArray(c.entries)||c.entries.length>200||
   !exact(c.learning,['schema','atlasRevision','mappingRevision','entries'])||
   c.learning.schema!=='visible-medicine.regional-reference-learning/1'||
   c.learning.atlasRevision!==r.atlasRevision||c.learning.mappingRevision!==r.mappingRevision||
   !Array.isArray(c.learning.entries)||c.learning.entries.length>100||JSON.stringify(c).length>2000000)return null;
  const targets=c.entries.flatMap(row=>Array.isArray(row?.targets)?row.targets:[])
   .filter(t=>t?.id===r.target&&t.relation===r.relation);
  if(!targets.length||targets.some(t=>!exact(t,['kind','id','label','side','region','sourceHash','specimenRevision','relation','href'])||
   !sameIdentity(identity(t),identity(targets[0]))))return null;
  const entries=c.learning.entries.filter(e=>e?.target?.id===r.target&&e?.target?.relation===r.relation);
  if(entries.length!==1||!regionalLearningEntryValid(entries[0]))return null;
  const entry=entries[0];
  if(entry.revision!==r.teachingRevision||!sameIdentity(entry.target,identity(targets[0])))return null;
  if(await digest({version:1,atlasRevision:c.atlasRevision,entries:c.entries})!==r.mappingRevision)return null;
  const {revision,...content}=entry;
  if(await regionalLearningRevision(r.atlasRevision,r.mappingRevision,content)!==revision)return null;
  return freeze({atlasRevision:r.atlasRevision,mappingRevision:r.mappingRevision,entry});
 }catch{return null;}
}

import {isRegionalMriLearning,type RegionalMriLearning} from './regional-mri-learning.ts';

export type RegionalLearningReviewRequest={target:string;relation:'same-structure'|'parent-reference'|'group-reference';atlasRevision:string;mappingRevision:string;teachingRevision:string};
const keys=['target','relation','atlasRevision','mappingRevision','teachingRevision'] as const;
const hash=/^[a-f0-9]{64}$/;

/** Public reference identity only. Parsing is neither authorization nor approval. */
export function parseRegionalLearningReviewRequest(params:Record<string,string|string[]|undefined>):RegionalLearningReviewRequest|null{
 if(!params||typeof params!=='object'||Array.isArray(params)||Object.keys(params).sort().join('|')!==[...keys].sort().join('|'))return null;
 if(keys.some(k=>typeof params[k]!=='string'))return null;
 const value=params as Record<typeof keys[number],string>;
 if(!/^[a-zA-Z0-9][a-zA-Z0-9:_.-]{0,239}$/.test(value.target)||!['same-structure','parent-reference','group-reference'].includes(value.relation)||
  !/^[a-f0-9]{40}$/.test(value.atlasRevision)||!hash.test(value.mappingRevision)||!hash.test(value.teachingRevision))return null;
 return {target:value.target,relation:value.relation as RegionalLearningReviewRequest['relation'],atlasRevision:value.atlasRevision,mappingRevision:value.mappingRevision,teachingRevision:value.teachingRevision};
}

/** Never include the MRI identity, proof key, scan paths or coordinates in a URL. */
export function regionalLearningReviewHref(proof:RegionalMriLearning|unknown):string|null{
 if(!isRegionalMriLearning(proof))return null;
 const request=parseRegionalLearningReviewRequest({target:proof.entry.target.id,relation:proof.entry.target.relation,
  atlasRevision:proof.atlasRevision,mappingRevision:proof.mappingRevision,teachingRevision:proof.entry.revision});
 return request?'/workspace/atlas-review/reference-learning?'+new URLSearchParams(request):null;
}

import {regionalMri3dComparison,type Regional3dCatalogue,type Regional3dTarget} from './regional-mri-3d-comparison.ts';
import type {RegionalMriPackage,RegionalLoadedSeries,RegionalLoadedAnnotation} from './regional-mri-package.ts';

export const regionalLearningTopics=['anatomy','function','mri','ct','xray','ultrasound','pathology','clinical'] as const;
export type RegionalLearningTopic=typeof regionalLearningTopics[number];
export const regionalLearningLabels:Record<RegionalLearningTopic,string>={anatomy:'Anatomy',function:'Function',mri:'MRI',ct:'CT',xray:'X-ray',ultrasound:'Ultrasound',pathology:'Pathology',clinical:'Clinical'};
export type RegionalLearningReference={url:string;title:string};
export type RegionalLearningSection={id:RegionalLearningTopic;title:string;body:string;bullets:string[];note:string|null;readiness:'draft'|'pending'|'identity-only';references:RegionalLearningReference[]};
export type RegionalLearningTarget=Pick<Regional3dTarget,'id'|'kind'|'label'|'side'|'sourceHash'|'specimenRevision'|'relation'>;
export type RegionalLearningEntry={target:RegionalLearningTarget;revision:string;topics:RegionalLearningSection[];limitations:string[];reflection:{question:string;answer:string;references:RegionalLearningReference[]}|null};
export type RegionalLearningCatalogue={schema:'visible-medicine.regional-reference-learning/1';atlasRevision:string;mappingRevision:string;entries:RegionalLearningEntry[]};
export type RegionalMriLearning={key:string;atlasRevision:string;mappingRevision:string;entry:Readonly<RegionalLearningEntry>;target:Readonly<Regional3dTarget&{oppositeSide:boolean}>};
const owned=new WeakSet<object>(),hash=/^[a-f0-9]{64}$/;
const exact=(v:unknown,keys:string[]):v is Record<string,unknown>=>!!v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join('|')===[...keys].sort().join('|');
const text=(v:unknown,max=12000):v is string=>typeof v==='string'&&v.length<=max&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(v);
const strings=(v:unknown,max=32):v is string[]=>Array.isArray(v)&&v.length<=max&&v.every(s=>text(s));
function references(v:unknown):v is RegionalLearningReference[]{
 return Array.isArray(v)&&v.length<=32&&v.every(r=>{
  if(!exact(r,['url','title'])||!text(r.title,600)||!r.title||!text(r.url,2000))return false;
  try{const u=new URL(r.url);return u.protocol==='https:'&&!u.username&&!u.password&&u.hostname.includes('.')&&!u.hostname.endsWith('.localhost')&&!u.hostname.endsWith('.local')&&!/^(?:[\d.]+|\[.*\])$/.test(u.hostname);}catch{return false;}
 });
}
export function regionalLearningEntryValid(v:unknown):v is RegionalLearningEntry{
 if(!exact(v,['target','revision','topics','limitations','reflection'])||typeof v.revision!=='string'||!hash.test(v.revision)||
  !exact(v.target,['id','kind','label','side','sourceHash','specimenRevision','relation'])||!strings(v.limitations,16)||
  !Array.isArray(v.topics)||v.topics.length!==regionalLearningTopics.length)return false;
 const t=v.target;
 if(!text(t.id,240)||!t.id||!text(t.label,600)||!t.label||!['body','specimen'].includes(String(t.kind))||!['left','right'].includes(String(t.side))||
  typeof t.sourceHash!=='string'||!hash.test(t.sourceHash)||!(t.specimenRevision===null||typeof t.specimenRevision==='string'&&hash.test(t.specimenRevision))||
  !['same-structure','parent-reference','group-reference'].includes(String(t.relation)))return false;
 if(new Set(v.topics.map(s=>s?.id)).size!==regionalLearningTopics.length)return false;
 for(const s of v.topics){if(!exact(s,['id','title','body','bullets','note','readiness','references'])||!regionalLearningTopics.includes(s.id as RegionalLearningTopic)||
  !text(s.title,600)||!s.title||!text(s.body)||!s.body||!strings(s.bullets)||!(s.note===null||text(s.note,6000))||
  !['draft','pending','identity-only'].includes(String(s.readiness))||!references(s.references))return false;}
 return v.reflection===null||exact(v.reflection,['question','answer','references'])&&text(v.reflection.question)&&!!v.reflection.question&&text(v.reflection.answer)&&!!v.reflection.answer&&references(v.reflection.references);
}
const canonical=(v:unknown):string=>Array.isArray(v)?'['+v.map(canonical).join(',')+']':v&&typeof v==='object'?'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical((v as Record<string,unknown>)[k])).join(',')+'}':JSON.stringify(v);
/** Content integrity only, never authorization, clinical acceptance or registration. */
export async function regionalLearningRevision(atlasRevision:string,mappingRevision:string,entry:Omit<RegionalLearningEntry,'revision'>):Promise<string>{
 const bytes=new TextEncoder().encode(canonical({schema:'visible-medicine.regional-reference-learning/1',atlasRevision,mappingRevision,entry}));
 return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');
}
function freeze<T>(v:T):T{if(v&&typeof v==='object'){for(const item of Object.values(v))freeze(item);Object.freeze(v);}return v;}
export function isRegionalMriLearning(v:unknown):v is RegionalMriLearning{return !!v&&typeof v==='object'&&owned.has(v);}
/** Verified local MRI geometry and explicit current public mapping precede teaching. */
export async function resolveRegionalMriLearning(source:{revision:string;region:string},catalogue:Regional3dCatalogue|null,pkg:RegionalMriPackage,study:RegionalLoadedSeries,overlay:RegionalLoadedAnnotation,targetId:string):Promise<RegionalMriLearning|null>{
 try{
  const sourceRevision=source.revision;
  const comparison=regionalMri3dComparison(source,catalogue,pkg,study,overlay),learning=catalogue?.learning;
  if(!comparison||comparison.provisional||overlay.purpose!=='scoped-display'||overlay.annotation.review.status!=='accepted-scoped'||
   !exact(learning,['schema','atlasRevision','mappingRevision','entries'])||learning.schema!=='visible-medicine.regional-reference-learning/1'||
   learning.atlasRevision!==comparison.atlasRevision||learning.mappingRevision!==comparison.mappingRevision||!Array.isArray(learning.entries)||learning.entries.length>100||
   JSON.stringify(learning).length>2000000)return null;
  const targets=comparison.targets.filter(t=>t.id===targetId);if(targets.length!==1)return null;const target=targets[0];
  const entries=learning.entries.filter(e=>e?.target?.id===targetId&&e?.target?.relation===target.relation);if(entries.length!==1||!regionalLearningEntryValid(entries[0]))return null;
  // Detach before the digest await; later mutation must not alter checked text.
  const entry=structuredClone(entries[0]);for(const k of Object.keys(entry.target) as (keyof RegionalLearningTarget)[])if(entry.target[k]!==target[k])return null;
  const {revision,...content}=entry;if(await regionalLearningRevision(comparison.atlasRevision,comparison.mappingRevision,content)!==revision)return null;
  const result=freeze({key:JSON.stringify([sourceRevision,study.series.id,study.series.image.sha256,overlay.annotation.id,overlay.annotation.review.revision,comparison.atlasRevision,comparison.mappingRevision,target.id,target.relation,revision]),atlasRevision:comparison.atlasRevision,mappingRevision:comparison.mappingRevision,entry,target:structuredClone(target)});
  owned.add(result);return result;
 }catch{return null;}
}

import {assertRegionalMriPackageOwnership,type RegionalMriPackage,type RegionalLoadedSeries,type RegionalLoadedAnnotation} from './regional-mri-package.ts';
import type {RegionalLearningCatalogue} from './regional-mri-learning.ts';
import {kneeReferenceSpecs,kneeBodyReferenceId,kneeReferencePin,type KneeReferenceSpec} from './regional-knee-3d-mappings.ts';
export type Regional3dTarget={kind:'body'|'specimen';id:string;label:string;side:'left'|'right';region:'leg'|'thigh'|'knee';
 sourceHash:string;specimenRevision:string|null;relation:KneeReferenceSpec['relation'];href:string};
export type Regional3dCatalogue={schema:'visible-medicine.regional-mri-3d/1';mriRevision:string;atlasRevision:string;mappingRevision:string;
 entries:{anatomyId:string;sourceSide:'left'|'right';targets:Regional3dTarget[]}[];learning?:RegionalLearningCatalogue};
type BoundSource={revision:string;region:string};
const hash=/^[a-f0-9]{64}$/,commit=/^[a-f0-9]{40}$/;
function targetCurrent(target:Regional3dTarget,spec:KneeReferenceSpec,side:'left'|'right',revision:string):boolean{
 const pin=kneeReferencePin(spec,side);
 if(target.kind!==spec.kind||target.region!==spec.region||target.relation!==spec.relation||!hash.test(target.sourceHash)||
  target.sourceHash!==pin.sourceHash||target.specimenRevision!==pin.specimenRevision||target.label!==pin.label||!['left','right'].includes(target.side)||
  typeof target.href!=='string'||!target.href.startsWith('/atlas/'))return false;
 const url=new URL(target.href,'https://visible-medicine.invalid');
 if(url.origin!=='https://visible-medicine.invalid'||url.hash||url.username||url.password)return false;
 const params=url.searchParams,keys=[...params.keys()];if(new Set(keys).size!==keys.length||params.get('atlasRevision')!==revision)return false;
 if(spec.kind==='body')return target.side===side&&target.id===kneeBodyReferenceId(spec,side)&&target.specimenRevision===null&&url.pathname==='/atlas/3d'&&
  keys.length===6&&['region','study','structure','side','source','atlasRevision'].every(k=>keys.includes(k))&&params.get('region')===spec.region&&params.get('study')==='1'&&
  params.get('structure')===target.id&&params.get('side')===side&&params.get('source')===target.sourceHash;
 return target.side==='right'&&target.id===`vm:reference:um-5t6tz7-v1-2:knee:${spec.slug}`&&typeof target.specimenRevision==='string'&&hash.test(target.specimenRevision)&&
  url.pathname==='/atlas/lower-limb-3d'&&keys.length===7&&['specimen','specimenScope','specimenPart','specimenSource','specimenRevision','specimenView','atlasRevision'].every(k=>keys.includes(k))&&
  params.get('specimen')==='um-limb-1'&&params.get('specimenScope')==='knee'&&params.get('specimenPart')===target.id&&params.get('specimenSource')===target.sourceHash&&
  params.get('specimenRevision')===target.specimenRevision&&params.get('specimenView')==='anterior';
}
/** Reference navigation only. No patient positions, source identifiers or image revision enter a URL. */
export function regionalMri3dComparison(source:BoundSource,catalogue:Regional3dCatalogue|null,pkg:RegionalMriPackage,study:RegionalLoadedSeries,overlay:RegionalLoadedAnnotation){
 try{
  assertRegionalMriPackageOwnership(pkg,study,overlay);
  const a=overlay.annotation;
  if(!catalogue||catalogue.schema!=='visible-medicine.regional-mri-3d/1'||!hash.test(source.revision)||source.revision!==pkg.revision||
   source.region!=='knee'||pkg.manifest.region!==source.region||catalogue.mriRevision!==source.revision||!commit.test(catalogue.atlasRevision)||!hash.test(catalogue.mappingRevision)||
   !Array.isArray(catalogue.entries)||catalogue.entries.length>200||!['left','right'].includes(a.laterality)||a.review.status==='deferred'||a.geometry.kind==='none')return null;
  const side=a.laterality as 'left'|'right',matches=catalogue.entries.filter(e=>e.anatomyId===a.anatomyId&&e.sourceSide===side);
  if(matches.length!==1)return null;
  const row=matches[0];if(!Array.isArray(row.targets)||!row.targets.length||row.targets.length>3)return null;
  const specs=kneeReferenceSpecs.filter(s=>s.anatomyId===a.anatomyId),seen=new Set();
  for(const target of row.targets){const spec=specs.find(s=>s.kind===target.kind);
   if(!spec||seen.has(target.id)||!targetCurrent(target,spec,side,catalogue.atlasRevision))return null;seen.add(target.id);}
  return Object.freeze({anatomyId:a.anatomyId,sourceSide:side,reviewStatus:a.review.status,sourceReviewRevision:a.review.revision,
   atlasRevision:catalogue.atlasRevision,mappingRevision:catalogue.mappingRevision,provisional:overlay.purpose==='provisional-inspection',
   targets:row.targets.map(t=>Object.freeze({...t,oppositeSide:t.side!==side}))});
 }catch{return null;}
}

import raw from '../atlas-review/public/models/bodyparts3d/full-body/catalog.json';
import review from '../atlas-review/manifest.json';
import {bodyDisplayCatalog} from '../atlas-review/lib/body-display-catalog';
import {bodyTeachingLoader} from '../atlas-review/lib/body-teaching-loader';
import {kneeDefinition} from '../atlas-review/lib/um-limb-studies';
import {specimenTeachingFor} from '../atlas-review/lib/um-limb-teaching';
import {specimenClinicalReferences} from '../atlas-review/content/um-limb-clinical';
import {parseStudyLink,resolveStudyLink} from '../atlas-review/lib/study-links';
import {parseSpecimenLink} from '../atlas-review/lib/specimen-links';
import {resolveSpecimenLink} from '../atlas-review/lib/um-limb-navigation';
import type {BodyCatalog} from '../atlas-review/app/body-types';
import {kneeReferenceSpecs,kneeBodyReferenceId,kneeReferencePin} from './regional-knee-3d-mappings';
import type {Regional3dCatalogue,Regional3dTarget} from './regional-mri-3d-comparison';
import {regionalLearningTopics,regionalLearningLabels,regionalLearningRevision,regionalLearningEntryValid,
 type RegionalLearningCatalogue,type RegionalLearningEntry,type RegionalLearningReference,type RegionalLearningSection} from './regional-mri-learning';

const canonical=bodyDisplayCatalog(raw as unknown as BodyCatalog);
const structures=new Map(canonical.structures.map(s=>[s.id,JSON.stringify(s)]));
const bundles=new Map(canonical.bundles.map(b=>[b.id,JSON.stringify(b)]));
const hash=/^[a-f0-9]{64}$/;
const pending=(id:typeof regionalLearningTopics[number]):RegionalLearningSection=>({id,title:regionalLearningLabels[id],body:'Pending source-bound teaching.',bullets:[],note:null,readiness:'pending',references:[]});
const referenceTitles=new Map(Object.values(specimenClinicalReferences).map(ref=>[ref.url,ref.title]));
function references(urls:readonly string[]|undefined):RegionalLearningReference[]{
 return [...new Set((urls??[]).filter(url=>{try{const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password&&u.hostname!=='localhost';}catch{return false;}}))]
  .map(url=>({url,title:referenceTitles.get(url)??url}));
}
